from flask import Flask, request, jsonify
import joblib
import numpy as np
import time

app = Flask(__name__)
pipeline = joblib.load("inference_pipeline_v1.joblib")  # loaded once, at startup

@app.route("/predict", methods=["POST"])
def predict():
    start_time = time.time()
    try:
        payload = request.get_json()
        features = np.array([payload["features"]])
        prediction = pipeline.predict(features)[0]
        latency_ms = (time.time() - start_time) * 1000
        return jsonify({
            "prediction": int(prediction),
            "latency_ms": round(latency_ms, 2)
        })
    except Exception as error:
        return jsonify({"error": "prediction failed", "fallback": 0}), 500

if __name__ == "__main__":
    app.run(port=8000)
    print("Serving predictions at /predict, pipeline preloaded and resident in memory")
